// 纯检查/真实差量形状门；未挂Common observer，不宣称原World已保护任何库存。
#include "resident/domains/growth/growth_market_resource_contract.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
    Owner merchant{Owner::Kind::organization,"merchant",{},{}},person{Owner::Kind::actor,"buyer",{}, {}};InventoryView inventory{"market",merchant,100,0,{{"lot:1","millet",{},5,merchant,{}},{"lot:2","millet",{},7,merchant,{}}},{}};auto catalog=std::make_shared<CommonCatalog>();CommonState seed;seed.identity.world_id[0]=1;seed.inventories.insert("market",inventory);CommonStore common(seed,catalog);ProtectedMarketAccounts policy;policy.inventories.insert("market",RequiredContainer{merchant,100});MarketRecipeAuthorization auth;auth.source_identity=seed.identity;auth.original_business_key="action:9";auth.kind=MarketCauseKind::growth_trade;auth.expected_market_legs={{"market","millet",merchant,-8}};ResourceRecipe buy{{TransferLots{"market","bag","millet",8,{merchant},{},person}},{}};
    auto inspected=inspect_protected_market_recipe(common,policy,buy,&auth);check(inspected.ok&&inspected.value.inventories.size()==1,"original trade permitted with exact scope");check(!inspect_protected_market_recipe(common,policy,buy,nullptr).ok,"unscoped trade denied");auto wrong=auth;wrong.expected_market_legs[0].signed_quantity=-7;check(!inspect_protected_market_recipe(common,policy,buy,&wrong).ok,"wrong planned quantity denied");auto forbidden=buy;forbidden.operations.push_back(SetInventoryOwner{"market",person});check(!inspect_protected_market_recipe(common,policy,forbidden,&auth).ok,"later forbidden leg rejects whole recipe");ResourceRecipe no_bump{{AdjustLots{"market",{{"lot:1",-1}},false}},{}};check(!inspect_protected_market_recipe(common,policy,no_bump,&auth).ok,"no bump bypass denied");
    auto self=buy;std::get<TransferLots>(self.operations[0]).destination_id="market";check(!inspect_protected_market_recipe(common,policy,self,&auth).ok,"same protected source and destination denied");
    auto nonfifo=inventory;nonfifo.lots[0].quantity=4;nonfifo.lots.erase(nonfifo.lots.begin()+1);nonfifo.revision=1;check(!capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,nonfifo,10,12).ok,"equal net quantity cannot consume later lot first");
    auto after=inventory;after.lots.erase(after.lots.begin());after.lots[0].quantity=4;after.revision=1;auto change=capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,10,12);check(change.ok&&change.value.lots.size()==2,"actual FIFO depletion captured");after.revision=0;check(!capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,10,12).ok,"missing physical revision rejected");after.revision=1;after.lots[0].owner=person;check(!capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,10,12).ok,"owner mutation rejected");
    auth.expected_market_legs={{"market","millet",merchant,5}};ResourceRecipe sell{{TransferLots{"bag","market","millet",5,{person},{},merchant}},{}};inspected=inspect_protected_market_recipe(common,policy,sell,&auth);check(inspected.ok,"original sale destination scope");after=inventory;after.lots.push_back({"lot:10","millet",{},2,merchant,{}});after.lots.push_back({"lot:11","millet",{},3,merchant,{}});after.revision=2;check(capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,10,12).ok,"actual split source creates two market lots");check(!capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,11,12).ok,"invented lot outside actual allocation range");
    auth.kind=MarketCauseKind::local_production;ResourceRecipe production{{AddLot{"market","millet",5,merchant,{}}},{}};inspected=inspect_protected_market_recipe(common,policy,production,&auth);check(inspected.ok&&!capture_protected_market_inventory(policy,inspected.value.inventories[0],inventory,after,10,12).ok,"single AddLot cannot forge fragmented receipt");
    common.state().inventories.find("market")->lots[0].reserved_by=ReservationRef{"action:77"};ResourceRecipe release{{ReleaseActionResources{"action:77"}},{}};check(!inspect_protected_market_recipe(common,policy,release,nullptr).ok,"indirect reservation release guarded");common.state().inventories.find("market")->lots[0].reserved_by.clear();check(compare_boundary(encode_common_state(seed),encode_common_state(common.state())).exact(),"pure guard/capture mutated assets or IDs");std::cout<<"GROWTH_MARKET_RESOURCE_CONTRACT "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_MARKET_RESOURCE_CONTRACT "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
